const items = $input.all();
return items.map(item => {
  const d = item.json;
  const step = d.touch_step || 1;
  const name = d.lead_name || 'there';
  const meta = d.lead_metadata || {};
  const industry = meta.industry || 'business';
  const bizName = meta.business_name || 'your business';

  let msg = '';
  if (step === 1) {
    msg = `Hi ${name}! 👋 Congratulations on starting ${bizName}! We help new ${industry} businesses get their websites ready. Would you like me to send over a few relevant design options?`;
  } else if (step === 2) {
    msg = `Hi ${name}! 🎨 Just wanted to clarify about the designs — they are fully customized for your brand logo, colors, and products. Would you like to see how we can customize one for ${bizName}?`;
  } else if (step === 3) {
    msg = `Hi ${name}! A professional website helps ${industry} customers send inquiries directly on WhatsApp and build trust. Would you like to see a live example?`;
  } else if (step === 4) {
    msg = `Hi ${name}! One mistake new businesses make is waiting until everything is perfect. You can start with essential pages now and expand later! Would you like me to suggest what pages your website should include?`;
  } else if (step === 5) {
    msg = `Hi ${name}! If you are still planning, that is completely fine. We can give you a simple recommendation on initial page structure and budget. Would you like a simple recommendation?`;
  } else if (step === 6) {
    msg = `Hi ${name}! Just so you have an idea, our website packages start from ₹9,999 depending on pages and features. Would you like me to explain the suitable options?`;
  } else {
    msg = `Hi ${name}! Checking in one last time regarding the website for ${bizName}. If you'd like to explore this now, simply reply WEBSITE and I'll help you with the next step!`;
  }

  return {
    json: {
      drip_id: d.drip_id,
      lead_id: d.lead_id,
      phone_number: d.phone_number,
      touch_step: step,
      message_text: msg
    }
  };
});
